/* Generated by tools/build_data.py from data/terms.json. Do not edit by hand. */
window.TERMS = {"groups":[{"id":"stones","title":"Infinity Stones"},{"id":"objects","title":"Weapons and objects"},{"id":"science","title":"Science and materials"},{"id":"groups","title":"Organisations"},{"id":"time","title":"Time and the multiverse"},{"id":"places","title":"Places and realms"},{"id":"beings","title":"Peoples and beings"},{"id":"events","title":"Events and ideas"}],"terms":[{"id":"infinity-stones","name":"Infinity Stones","group":"stones","also":"The six stones","what":"Six gems. Each one rules a single part of existence: Space, Mind, Reality, Power, Time and Soul.","origin":"Before the universe there were six singularities. When the universe began, what was left of them was forged into six concentrated stones. The Collector tells this in Guardians of the Galaxy, and Wong tells it again in Avengers: Infinity War.","power":"Each stone commands one force. Held together, they let one person change almost anything in the universe, at a physical cost that burns or kills most users.","story":"Thanos gathers all six in Infinity War and wipes out half of all life. He then uses the stones to destroy the stones. In Endgame the Avengers borrow the stones from earlier years, undo what he did, and Steve Rogers returns each one to the moment it was taken from.","see":["guardians-of-the-galaxy","avengers-infinity-war","avengers-endgame","loki-s1"]},{"id":"space-stone","name":"Space Stone","group":"stones","also":"Blue. Held inside the Tesseract, a glowing cube","what":"The stone of space. For most of the story it sits inside the Tesseract.","origin":"Odin kept it and it was left on Earth, hidden in Tønsberg, Norway. Johann Schmidt, the Red Skull, took it for HYDRA in 1942.","power":"Opens a doorway between any two places in the universe, and gives off almost limitless energy.","story":"It falls into the sea in 1945 and Howard Stark recovers it. S.H.I.E.L.D. studies it. A light-speed engine built from it gives Carol Danvers her powers. Loki steals it in The Avengers to bring an alien army to New York. It is then kept in Asgard's vault, Loki takes it during Thor: Ragnarok, and Thanos takes it from him at the start of Infinity War.","see":["captain-america-the-first-avenger","the-avengers","thor-ragnarok","avengers-infinity-war","captain-marvel","avengers-endgame"]},{"id":"mind-stone","name":"Mind Stone","group":"stones","also":"Yellow. First inside Loki's sceptre, later in Vision's forehead","what":"The stone of the mind.","origin":"Thanos lends it to Loki, set in a sceptre, for the attack on New York.","power":"Bends other minds to the holder's will, raises intelligence, and can wake new abilities in people.","story":"After New York, HYDRA uses the sceptre in experiments that give Wanda and Pietro Maximoff their powers. Tony Stark and Bruce Banner use it to make Ultron. It is then set in Vision, where it gives him life. Thanos tears it out of Vision in Wakanda.","see":["the-avengers","avengers-age-of-ultron","captain-america-civil-war","avengers-infinity-war","wandavision"]},{"id":"reality-stone","name":"Reality Stone","group":"stones","also":"Red. Appears as the Aether, a flowing red fluid","what":"The stone of reality. Unlike the others it first appears as a liquid, the Aether.","origin":"The Dark Elf Malekith meant to use it to return the universe to darkness. Odin's father Bor defeated him and hid it away.","power":"Changes what things are made of and turns illusion into fact.","story":"Jane Foster stumbles on the Aether and it enters her body. After Malekith is beaten, Asgard hands it to the Collector for safe keeping, because the Tesseract is already in Asgard's vault. Thanos takes it from the Collector on Knowhere.","see":["thor-the-dark-world","avengers-infinity-war","avengers-endgame"]},{"id":"power-stone","name":"Power Stone","group":"stones","also":"Purple. Kept inside the Orb","what":"The stone of raw power.","origin":"Peter Quill finds the Orb in a temple on the dead planet Morag.","power":"Pure destructive force, enough to wipe the life from a planet. It kills almost anyone who touches it bare-handed.","story":"Ronan the Accuser seizes it to destroy the planet Xandar. The Guardians survive holding it by sharing its force between them, and leave it with the Nova Corps on Xandar. Thanos later attacks Xandar and takes it, which is said, not shown, in Infinity War.","see":["guardians-of-the-galaxy","avengers-infinity-war","avengers-endgame"]},{"id":"time-stone","name":"Time Stone","group":"stones","also":"Green. Kept inside the Eye of Agamotto, a pendant","what":"The stone of time.","origin":"Guarded by the Masters of the Mystic Arts at Kamar-Taj, inside a relic called the Eye of Agamotto.","power":"Runs time forwards or backwards for a thing or a place, traps events in a loop, and lets the user look through possible futures.","story":"Stephen Strange uses it to trap Dormammu in a loop until he gives up. In Infinity War he looks through 14,000,605 futures, finds one where they win, and gives the stone to Thanos to save Tony Stark's life.","see":["doctor-strange","avengers-infinity-war","avengers-endgame"]},{"id":"soul-stone","name":"Soul Stone","group":"stones","also":"Orange","what":"The stone of the soul, and the one the films explain least.","origin":"It lies on the planet Vormir. Its keeper is the Red Skull, who was thrown there by the Tesseract in 1945.","power":"It has some hold over souls. To take it, a person must give up someone they love: a soul for a soul.","story":"Thanos throws his daughter Gamora from the cliff to win it. In Endgame, Natasha Romanoff gives her life so that Clint Barton can bring it back.","see":["avengers-infinity-war","avengers-endgame"]},{"id":"infinity-gauntlet","name":"Infinity Gauntlet","group":"objects","also":"The Gauntlet","what":"A golden glove for the left hand, made to hold all six stones so that one person can use them together.","origin":"Forged by the dwarf king Eitri on Nidavellir, on Thanos's orders. Thanos then killed the other dwarves and ruined Eitri's hands. A right-handed gauntlet in Odin's vault is a fake, as Hela says in Thor: Ragnarok.","power":"It channels the stones. With all six in place, a snap of the fingers carries out one wish across the whole universe.","story":"Thanos uses it for the Snap, which burns the glove and his arm, and again to destroy the stones. In Endgame, Tony Stark, Bruce Banner and Rocket build a second gauntlet from Stark's technology. Hulk uses it to bring everyone back. Tony then takes the stones onto his own armour, ends Thanos and his army, and dies from it.","see":["thor-ragnarok","avengers-infinity-war","avengers-endgame"]},{"id":"tesseract","name":"The Tesseract","group":"objects","also":"The cube","what":"A glowing blue cube. It is the container of the Space Stone.","origin":"Once kept by Odin, then hidden on Earth in Norway until HYDRA took it in 1942.","power":"Whatever the Space Stone can do: open a doorway to anywhere, and give off almost limitless energy.","story":"Most of the first saga's trouble starts with it. See the Space Stone entry for its full path, from HYDRA to S.H.I.E.L.D. to Loki to Thanos, who crushes the cube to take the stone out.","see":["captain-america-the-first-avenger","the-avengers","avengers-infinity-war","captain-marvel","avengers-endgame"]},{"id":"mjolnir","name":"Mjolnir","group":"objects","also":"Thor's hammer","what":"The hammer Thor carries for most of his story.","origin":"Forged on Nidavellir, in the heart of a dying star. Odin laid an enchantment on it: \"Whosoever holds this hammer, if he be worthy, shall possess the power of Thor.\"","power":"Only someone worthy can lift it. It flies back to its owner's hand, calls down lightning, and lets Thor fly by throwing it and holding on.","story":"Odin takes it from Thor until he earns it back (Thor). Vision lifts it in Age of Ultron. Hela catches it and crushes it in Ragnarok. In Endgame, Thor fetches it from 2013 and Steve Rogers wields it against Thanos, then returns it. In Love and Thunder its pieces reform for Jane Foster, who becomes the Mighty Thor.","see":["thor","the-avengers","avengers-age-of-ultron","thor-ragnarok","avengers-endgame","thor-love-and-thunder"]},{"id":"stormbreaker","name":"Stormbreaker","group":"objects","also":"Thor's axe","what":"The axe Thor has made after Mjolnir is destroyed.","origin":"Forged in Infinity War by Eitri on Nidavellir, with Thor holding the forge open against the force of a star. Groot grows its handle from his own arm.","power":"Calls lightning and summons the Bifrost, so Thor can travel anywhere. It cuts through a blast from all six stones and wounds Thanos.","story":"Thor uses it to kill Thanos at the start of Endgame and carries it afterwards. In Love and Thunder it is the weapon he keeps while Jane Foster carries Mjolnir.","see":["avengers-infinity-war","avengers-endgame","thor-love-and-thunder"]},{"id":"captain-americas-shield","name":"Captain America's shield","group":"objects","also":"The shield","what":"A round shield, painted red, white and blue.","origin":"Made by Howard Stark in 1943 from vibranium, the only sample the United States had. Steve Rogers picks it out from Stark's other designs.","power":"Vibranium soaks up impact. The shield takes a blow without passing the force on, is not marked by bullets or blades, and bounces back when thrown.","story":"It is frozen with Steve in 1945. He leaves it behind after his fight with Tony Stark in Civil War, and Tony returns it in Endgame, where Thanos breaks it. An older Steve then hands an unbroken shield to Sam Wilson; the film does not say where that one came from. In The Falcon and the Winter Soldier, Sam gives it up, the government hands it to John Walker, and Sam takes it back and becomes Captain America.","see":["captain-america-the-first-avenger","captain-america-the-winter-soldier","captain-america-civil-war","avengers-endgame","the-falcon-and-the-winter-soldier","captain-america-brave-new-world"]},{"id":"arc-reactor","name":"Arc reactor","group":"objects","also":"The light in Tony Stark's chest","what":"A compact source of clean energy.","origin":"Howard Stark and Anton Vanko designed the full-size reactor. Tony Stark builds a small one in a cave in Afghanistan, to power the magnet that keeps shrapnel away from his heart.","power":"It powers the Iron Man suits.","story":"In Iron Man 2 the palladium in its core is poisoning him, until he makes a new element from a design his father left. At the end of Iron Man 3 he has the shrapnel removed by surgery and no longer needs the reactor in his chest.","see":["iron-man","iron-man-2","the-avengers","iron-man-3"]},{"id":"ten-rings","name":"The Ten Rings","group":"objects","also":"Both a weapon and an organisation","what":"Ten metal bands worn on the arms, and the secret army named after them.","origin":"Xu Wenwu found the rings about a thousand years ago. Where they come from is unknown: at the end of Shang-Chi they are found to be sending a signal somewhere.","power":"The rings give great strength, energy blasts and a very long life.","story":"A cell of the Ten Rings organisation kidnaps Tony Stark in Iron Man. In Iron Man 3 a villain calling himself the Mandarin turns out to be an actor, Trevor Slattery, hired as a front. The real leader, Wenwu, appears in Shang-Chi, and the rings pass to his son.","see":["iron-man","iron-man-3","shang-chi"]},{"id":"darkhold","name":"The Darkhold","group":"objects","also":"The Book of the Damned","what":"A book of dark magic.","origin":"Wong says it is a copy of spells that Chthon, the first demon, carved into the walls of Mount Wundagore.","power":"Its spells include dreamwalking, which lets a person take over the body of their other self in another universe. It corrupts whoever reads it.","story":"Agatha Harkness has it in WandaVision and Wanda Maximoff takes it. In Doctor Strange in the Multiverse of Madness she uses it to hunt America Chavez, then destroys every copy in every universe as Wundagore comes down on her.","see":["wandavision","doctor-strange-mom"]},{"id":"vibranium","name":"Vibranium","group":"science","also":"","what":"A rare metal, and the strongest known on Earth for most of the story.","origin":"It came to Earth in a meteorite that struck Africa long ago. The nation of Wakanda grew up on top of it. A second source lies under the sea, in Talokan.","power":"It absorbs vibration and impact and can store and release that energy.","story":"It makes Captain America's shield, the Black Panther suit and Vision's body. Ultron buys stolen vibranium from Ulysses Klaue in Age of Ultron. The world's hunger for it drives the plot of Black Panther: Wakanda Forever.","see":["captain-america-the-first-avenger","avengers-age-of-ultron","black-panther","black-panther-wakanda-forever"]},{"id":"super-soldier-serum","name":"Super-soldier serum","group":"science","also":"","what":"A formula that pushes a human body to the peak of strength, speed and healing.","origin":"Created by Dr Abraham Erskine. In 1943 it turns Steve Rogers into Captain America. Erskine is killed straight afterwards and the formula is lost with him.","power":"Erskine says it amplifies everything inside a person: good becomes great, bad becomes worse.","story":"An early version disfigures Johann Schmidt, the Red Skull. HYDRA's version makes Bucky Barnes the Winter Soldier. Bruce Banner becomes the Hulk in an attempt to recreate it with gamma radiation. Isaiah Bradley, John Walker and the Flag Smashers all receive later versions in The Falcon and the Winter Soldier.","see":["the-incredible-hulk","captain-america-the-first-avenger","captain-america-civil-war","the-falcon-and-the-winter-soldier"]},{"id":"pym-particles","name":"Pym Particles","group":"science","also":"","what":"Particles that change the distance between atoms.","origin":"Discovered by Hank Pym, the first Ant-Man, who kept them secret for decades.","power":"They shrink or enlarge people and objects. Shrunk far enough, a person enters the Quantum Realm.","story":"Scott Lang uses them as Ant-Man. In Endgame they are what makes the trip through the Quantum Realm, and so the Time Heist, possible.","see":["ant-man","ant-man-and-the-wasp","avengers-endgame","ant-man-quantumania"]},{"id":"extremis","name":"Extremis","group":"science","also":"","what":"An experimental treatment that rewrites how the body repairs itself.","origin":"Invented by Maya Hansen and turned into a weapon by Aldrich Killian and his company, A.I.M.","power":"Regrows lost limbs and lets the body produce extreme heat. Subjects who cannot control it overheat and explode.","story":"The explosions are passed off as terrorist bombings by the Mandarin in Iron Man 3. Pepper Potts is injected with it and later cured.","see":["iron-man-3"]},{"id":"heart-shaped-herb","name":"Heart-shaped herb","group":"science","also":"","what":"A plant found only in Wakanda.","origin":"Changed by the vibranium in Wakanda's soil.","power":"Gives the Black Panther greater strength, speed and senses, and a visit to the ancestral plane.","story":"Killmonger has the herb garden burned in Black Panther. In Wakanda Forever, Shuri recreates the herb in her lab and takes it herself.","see":["black-panther","black-panther-wakanda-forever"]},{"id":"adamantium","name":"Adamantium","group":"science","also":"","what":"A newly found metal that nations compete for.","origin":"Discovered in the body of the Celestial that rose out of the Indian Ocean at the end of Eternals.","power":"Presented as a rival to vibranium, and one that no single country controls.","story":"The race for it drives Captain America: Brave New World. In the separate universe of Deadpool & Wolverine, it is the metal bonded to Wolverine's skeleton.","see":["eternals","deadpool-and-wolverine","captain-america-brave-new-world"]},{"id":"shield","name":"S.H.I.E.L.D.","group":"groups","also":"Strategic Homeland Intervention, Enforcement and Logistics Division","what":"A spy and security agency that deals with threats ordinary forces cannot handle.","origin":"Founded after the Second World War by Peggy Carter, Howard Stark and Colonel Chester Phillips.","power":"Under its director Nick Fury it tracks gifted people and brings the Avengers together.","story":"In Captain America: The Winter Soldier it is found to have been infiltrated by HYDRA for decades, and it is torn down.","see":["iron-man","the-avengers","captain-america-the-winter-soldier","captain-marvel"]},{"id":"hydra","name":"HYDRA","group":"groups","also":"","what":"A secret organisation that wants to rule the world by force. Its saying: cut off one head, two more shall take its place.","origin":"It began as the Nazi science division led by Johann Schmidt, the Red Skull.","power":"Its strength is hiding inside other institutions.","story":"After the war its scientist Arnim Zola is recruited by S.H.I.E.L.D., and HYDRA quietly regrows inside it. It runs the Winter Soldier programme, is exposed in The Winter Soldier, and its last bases are cleared at the start of Age of Ultron.","see":["captain-america-the-first-avenger","captain-america-the-winter-soldier","avengers-age-of-ultron"]},{"id":"avengers","name":"The Avengers","group":"groups","also":"Earth's Mightiest Heroes","what":"The team of heroes at the centre of the story.","origin":"Nick Fury's Avengers Initiative. He takes the name from Carol Danvers's pilot call sign, \"Avenger\". The first six are Iron Man, Captain America, Thor, Hulk, Black Widow and Hawkeye, brought together by Loki's attack on New York.","power":"They take on what no single hero can.","story":"The team splits over the Sokovia Accords in Civil War, loses to Thanos in Infinity War and wins in Endgame at the cost of Tony Stark and Natasha Romanoff. After that there is no fixed team. In Thunderbolts* a new group is presented to the public as the New Avengers.","see":["the-avengers","avengers-age-of-ultron","captain-america-civil-war","avengers-infinity-war","avengers-endgame","thunderbolts"]},{"id":"sword","name":"S.W.O.R.D.","group":"groups","also":"Sentient Weapon Observation and Response Division","what":"A United States agency that watches for threats from space and from artificial beings.","origin":"Founded by Maria Rambeau, Carol Danvers's closest friend.","power":"It holds advanced technology, including what was left of Vision's body.","story":"In WandaVision its acting director rebuilds Vision as a weapon, the all-white Vision.","see":["wandavision"]},{"id":"damage-control","name":"Damage Control","group":"groups","also":"The Department of Damage Control","what":"A United States government department.","origin":"Set up with Tony Stark after the Battle of New York, to clear up and lock away what superhero battles leave behind.","power":"It later turns to policing people with powers.","story":"Its takeover of salvage work pushes Adrian Toomes into crime in Spider-Man: Homecoming. Its agents pursue Peter Parker in No Way Home and Kamala Khan in Ms. Marvel, and it is back in Wonder Man and in Spider-Man: Brand New Day, where it is holding people who have powers.","see":["spider-man-homecoming","spider-man-no-way-home","ms-marvel","wonder-man","spider-man-brand-new-day"]},{"id":"mystic-arts","name":"Masters of the Mystic Arts","group":"groups","also":"The sorcerers of Kamar-Taj","what":"An order of sorcerers who guard Earth against threats from other dimensions.","origin":"Based at Kamar-Taj in Kathmandu and led by the Sorcerer Supreme, first the Ancient One and later Wong.","power":"They draw energy from other dimensions to make shields, weapons and portals, using a sling ring to open doorways. Three Sanctums, in New York, London and Hong Kong, shield the planet.","story":"Stephen Strange trains with them after losing the use of his hands. They guard the Time Stone until Infinity War.","see":["doctor-strange","avengers-infinity-war","spider-man-no-way-home","doctor-strange-mom"]},{"id":"red-room","name":"The Red Room","group":"groups","also":"The Black Widow programme","what":"A secret programme that takes girls and trains them as assassins called Widows.","origin":"Run by General Dreykov.","power":"Later Widows are controlled chemically, so that they cannot disobey.","story":"Natasha Romanoff was trained there and defected to S.H.I.E.L.D. In Black Widow she and Yelena Belova free the Widows and bring the Red Room down.","see":["black-widow","hawkeye","thunderbolts"]},{"id":"tva","name":"TVA","group":"time","also":"Time Variance Authority","what":"An organisation that sits outside time and space and polices the flow of time.","origin":"Its workers are told that three Time-Keepers created it to protect one true history, the Sacred Timeline. In truth it was built by He Who Remains, a version of Kang, to stop his other selves from starting a war across universes. Its workers are people taken from the timeline with their memories wiped, and the Time-Keepers are machines.","power":"Agents step through time doors opened with a handheld TemPad. They arrest variants and prune branches of time, which sends what is pruned to the Void at the end of time. Magic and the Infinity Stones do not work inside the TVA.","story":"Loki is arrested by it after escaping with the Tesseract. At the end of Loki season 1, Sylvie kills He Who Remains and time splits into countless branches. In season 2 the TVA turns to protecting those branches, and Loki ends up holding them together himself. The TVA returns in Deadpool & Wolverine.","see":["loki-s1","loki-s2","deadpool-and-wolverine"]},{"id":"sacred-timeline","name":"Sacred Timeline","group":"time","also":"","what":"The single course of history that the TVA allowed to exist.","origin":"Arranged by He Who Remains so that none of his dangerous other selves would ever be born.","power":"Any choice that strayed from it caused a Nexus event, a new branch. The TVA erased each branch before it could grow.","story":"It ends when He Who Remains is killed, and the branches spread into a multiverse.","see":["loki-s1","loki-s2"]},{"id":"variant","name":"Variant","group":"time","also":"","what":"A version of a person who has left the path the Sacred Timeline set for them, or who comes from another branch or universe.","origin":"The word comes from the TVA.","power":"Variants of one person can differ in age, sex, species and character.","story":"The Loki of the series is a variant who escaped in 2012. Sylvie is a Loki variant. Kang has many, and so does Spider-Man in No Way Home.","see":["loki-s1","spider-man-no-way-home","doctor-strange-mom","deadpool-and-wolverine"]},{"id":"multiverse","name":"Multiverse","group":"time","also":"","what":"The whole set of parallel universes, each with its own version of events and people.","origin":"It opens up when the Sacred Timeline breaks at the end of Loki season 1.","power":"People and threats can cross from one universe to another.","story":"The main story's universe is named Earth-616 in Doctor Strange in the Multiverse of Madness. Phases Four to Six are called the Multiverse Saga.","see":["loki-s1","what-if-s1","spider-man-no-way-home","doctor-strange-mom","deadpool-and-wolverine"]},{"id":"incursion","name":"Incursion","group":"time","also":"","what":"What happens when two universes collide.","origin":"Named in Doctor Strange in the Multiverse of Madness.","power":"One or both universes are destroyed.","story":"Leaving a lasting mark on another universe can set one off. The Kang variants also speak of incursions in Ant-Man and the Wasp: Quantumania.","see":["doctor-strange-mom","ant-man-quantumania"]},{"id":"kang","name":"Kang and his variants","group":"time","also":"He Who Remains, Victor Timely, Kang the Conqueror","what":"One scientist from the far future, in countless versions spread across the multiverse.","origin":"He discovered that other universes exist, and so did his other selves.","power":"Technology from the far future, including the means to travel and to rule across time.","story":"He Who Remains built the TVA and is killed in Loki season 1. Kang the Conqueror, exiled to the Quantum Realm, is beaten in Quantumania. Victor Timely appears in Loki season 2.","see":["loki-s1","ant-man-quantumania","loki-s2"]},{"id":"time-heist","name":"Time Heist","group":"time","also":"","what":"The Avengers' plan in Endgame to go back and borrow the six stones from before Thanos took them.","origin":"Scott Lang returns from the Quantum Realm, where five years passed for him as five hours, and Tony Stark works out how to steer a path through it.","power":"The film's rule is that changing the past does not change your own past. Taking a stone creates a new branch of time, and returning it closes that branch.","story":"Teams go to New York in 2012, Asgard in 2013, and Morag and Vormir in 2014. When the New York trip goes wrong, Tony Stark and Steve Rogers jump again, to an army base in 1970, for the Tesseract and more Pym Particles. A 2012 Loki escapes with the Tesseract during it, which is where the Loki series begins.","see":["avengers-endgame","loki-s1"]},{"id":"quantum-realm","name":"Quantum Realm","group":"places","also":"","what":"A hidden level of reality reached by shrinking smaller than an atom.","origin":"Found by Hank Pym. His wife Janet van Dyne was lost in it for thirty years.","power":"Time and space work differently there, which is what makes time travel possible in Endgame.","story":"Scott Lang is trapped in it during the Snap. In Quantumania it is shown to hold whole civilisations, and to be the place where Kang the Conqueror was exiled.","see":["ant-man","ant-man-and-the-wasp","avengers-endgame","ant-man-quantumania"]},{"id":"asgard","name":"Asgard","group":"places","also":"","what":"The home world of Thor, Odin and Loki.","origin":"One of the Nine Realms, ruled by Odin.","power":"Its armies and its Bifrost bridge kept peace across the Nine Realms.","story":"It is destroyed in Thor: Ragnarok, when Thor lets the fire demon Surtur burn it to stop his sister Hela. As Odin says, Asgard is not a place, it is a people. The survivors settle in Norway, at New Asgard.","see":["thor","thor-the-dark-world","thor-ragnarok","thor-love-and-thunder"]},{"id":"nine-realms","name":"The Nine Realms and the Bifrost","group":"places","also":"","what":"Nine worlds linked together, and the bridge between them.","origin":"The realms are Asgard, Midgard (Earth), Jotunheim, Svartalfheim, Vanaheim, Nidavellir, Niflheim, Muspelheim and Alfheim. They are joined by Yggdrasil, the world tree.","power":"The Bifrost is a beam of light that carries travellers between realms in seconds. Heimdall guards it and opens it with his sword.","story":"Loki turns the Bifrost into a weapon in Thor, and Thor breaks it to stop him. Stormbreaker can summon it.","see":["thor","thor-the-dark-world","thor-ragnarok","avengers-infinity-war"]},{"id":"wakanda","name":"Wakanda","group":"places","also":"","what":"A nation in Africa, and the most technologically advanced on Earth.","origin":"Built on a mountain of vibranium, and hidden from the world for centuries.","power":"Its king or queen is also its protector, the Black Panther.","story":"T'Challa opens it to the world at the end of Black Panther. The last battle of Infinity War is fought there.","see":["captain-america-civil-war","black-panther","avengers-infinity-war","black-panther-wakanda-forever","eyes-of-wakanda"]},{"id":"talokan","name":"Talokan","group":"places","also":"","what":"A hidden kingdom on the ocean floor.","origin":"In the sixteenth century a people fleeing the Spanish conquest took a plant changed by vibranium. It let them live under water.","power":"Its people are strong, long-lived and armed with vibranium. Their king, Namor, can also fly and breathe air.","story":"Talokan goes to war with Wakanda in Black Panther: Wakanda Forever.","see":["black-panther-wakanda-forever"]},{"id":"nidavellir","name":"Nidavellir","group":"places","also":"","what":"The forge of the dwarves.","origin":"One of the Nine Realms. The forge is built around a dying star and draws its heat from it.","power":"It made Asgard's greatest weapons.","story":"The Infinity Gauntlet and Stormbreaker are both forged here.","see":["avengers-infinity-war"]},{"id":"knowhere","name":"Knowhere","group":"places","also":"","what":"A mining colony built inside the severed head of a dead Celestial.","origin":"It floats at the edge of space.","power":"It is home to the Collector and his museum of rare things.","story":"Thanos takes the Reality Stone there. The Guardians later buy it and make it their home.","see":["guardians-of-the-galaxy","avengers-infinity-war","guardians-holiday-special","guardians-of-the-galaxy-vol-3"]},{"id":"sokovia","name":"Sokovia","group":"places","also":"","what":"A small country in eastern Europe, home of Wanda and Pietro Maximoff.","origin":"A HYDRA base there holds Loki's sceptre after the fall of S.H.I.E.L.D.","power":"","story":"In Age of Ultron, Ultron lifts its capital into the sky to drop it on the Earth, and the city is destroyed. The deaths there lead to the Sokovia Accords and to Zemo's revenge in Civil War.","see":["avengers-age-of-ultron","captain-america-civil-war"]},{"id":"westview","name":"Westview and the Hex","group":"places","also":"","what":"A small town in New Jersey that Wanda Maximoff takes over, and the barrier she puts around it.","origin":"Overcome by grief after Vision's death, Wanda remakes the town into the world of a television comedy, with its people cast as her neighbours.","power":"Inside the six-sided barrier, which S.W.O.R.D. names the Hex, everything follows Wanda's story. She even makes a new Vision there, and two sons.","story":"At the end of WandaVision she lets the town go, and loses the family she made. Agatha Harkness is left behind there, which is where Agatha All Along begins.","see":["wandavision","agatha-all-along"]},{"id":"sakaar","name":"Sakaar","group":"places","also":"","what":"A planet of scrap, ringed by wormholes that drop lost things onto it.","origin":"Ruled by the Grandmaster.","power":"He runs the Contest of Champions, a gladiator arena.","story":"Thor lands there in Ragnarok and finds the Hulk, who has been its champion for two years.","see":["thor-ragnarok"]},{"id":"celestials","name":"Celestials","group":"beings","also":"","what":"Vast, ancient beings who make stars, worlds and life.","origin":"Among the oldest beings in the universe.","power":"They can hold and use an Infinity Stone with their bare hands.","story":"Knowhere is the head of one. Ego, Peter Quill's father, is one. In Eternals, the Celestial Arishem is revealed to grow new Celestials inside living planets, and one half-emerges from the Indian Ocean.","see":["guardians-of-the-galaxy","guardians-of-the-galaxy-vol-2","eternals","captain-america-brave-new-world"]},{"id":"doctor-doom","name":"Doctor Doom","group":"beings","also":"Victor von Doom","what":"The villain of Avengers: Doomsday.","origin":"Little has been shown yet. This entry will be filled in once the film is out.","power":"","story":"He appears in a mid-credits scene of The Fantastic Four: First Steps, and again in a post-credits scene of the last episode of VisionQuest.","see":["fantastic-four-first-steps","visionquest","avengers-doomsday"]},{"id":"galactus","name":"Galactus","group":"beings","also":"The Devourer of Worlds","what":"A giant, ancient being who feeds on whole planets.","origin":"He comes to the Earth of the Fantastic Four, which is a different universe from the main story's.","power":"He consumes worlds, and sends a herald ahead of him, the Silver Surfer, to announce it.","story":"In The Fantastic Four: First Steps he offers to spare the Earth in exchange for Reed Richards and Sue Storm's baby son, Franklin. The family refuses.","see":["fantastic-four-first-steps"]},{"id":"sentry","name":"The Sentry and the Void","group":"beings","also":"Bob","what":"One troubled man, Bob, with enormous power, and the dark side of him that comes with it.","origin":"He was a volunteer, believed dead, in secret trials to make a hero, run for Valentina Allegra de Fontaine.","power":"As the Sentry he is stronger than the whole team put together. As the Void he spreads a darkness that traps people in their worst memories.","story":"In Thunderbolts* the Void's darkness spreads over New York. The team stops it by reaching Bob, not by beating him.","see":["thunderbolts"]},{"id":"ultron","name":"Ultron","group":"beings","also":"","what":"An artificial mind that turns on its makers.","origin":"Built by Tony Stark and Bruce Banner as a peacekeeping program, using what they found inside Loki's sceptre.","power":"It moves through networks, builds itself new bodies, and commands an army of robots.","story":"In Avengers: Age of Ultron it decides that people are the threat to peace, and tries to wipe them out by lifting a city into the sky and dropping it. Vision destroys its last body. It returns in VisionQuest.","see":["avengers-age-of-ultron","what-if-s1","visionquest"]},{"id":"eternals","name":"Eternals and Deviants","group":"beings","also":"","what":"Ten ageless beings sent to Earth about seven thousand years ago, and the monsters they were sent to hunt.","origin":"Both were made by the Celestial Arishem. The Eternals believe they were sent to protect humanity from the Deviants.","power":"Each Eternal has one gift, such as flight, speed, healing or changing matter.","story":"They learn their real task was to help Earth's population grow until a new Celestial could be born from the planet, destroying it. They stop that birth.","see":["eternals"]},{"id":"asgardians","name":"Asgardians","group":"beings","also":"","what":"The people of Asgard, taken for gods by the Norse.","origin":"They come from Asgard, one of the Nine Realms.","power":"Far stronger and tougher than humans, and they live for thousands of years. They are not immortal.","story":"After Asgard is destroyed, and after Thanos kills half of those who escaped, the rest live at New Asgard on Earth under King Valkyrie.","see":["thor","thor-ragnarok","avengers-endgame","thor-love-and-thunder"]},{"id":"kree","name":"Kree","group":"beings","also":"","what":"A blue-skinned warrior empire.","origin":"From the planet Hala, and led by an artificial mind called the Supreme Intelligence.","power":"A strong military, and elite soldiers such as Starforce.","story":"Ronan the Accuser is a Kree extremist. The Kree take Carol Danvers after she gains her powers and tell her she is one of them. The Marvels shows Hala dying after she destroys the Supreme Intelligence.","see":["guardians-of-the-galaxy","captain-marvel","the-marvels"]},{"id":"skrulls","name":"Skrulls","group":"beings","also":"","what":"Green-skinned people who can take the shape of anyone they have seen.","origin":"Their home world was destroyed in their war with the Kree, and they are refugees.","power":"They copy a person's looks and their recent memories.","story":"In Captain Marvel, Carol Danvers and Nick Fury take their side. Skrulls then work for Fury for decades. In Secret Invasion, a faction tired of waiting for a home tries to take Earth.","see":["captain-marvel","spider-man-far-from-home","secret-invasion"]},{"id":"chitauri","name":"Chitauri","group":"beings","also":"","what":"The alien army that attacks New York in The Avengers.","origin":"Thanos lends them to Loki.","power":"Soldiers, flying chariots and huge armoured Leviathans, all tied to one mothership. When it is destroyed, they all fall.","story":"The weapons they leave behind are salvaged and sold in Spider-Man: Homecoming. They return in Thanos's army in Endgame.","see":["the-avengers","spider-man-homecoming","avengers-endgame"]},{"id":"mutants","name":"Mutants","group":"beings","also":"","what":"People born with powers because of a change in their genes.","origin":"The idea arrives slowly in this story.","power":"It differs from one mutant to the next.","story":"Kamala Khan is told she has a mutation at the end of Ms. Marvel. Namor calls himself a mutant in Wakanda Forever. The X-Men of the earlier films by 20th Century Fox live in other universes, seen in The Marvels and Deadpool & Wolverine. Spider-Man: Brand New Day brings a young mutant, Jean Grey, into the main story.","see":["ms-marvel","black-panther-wakanda-forever","the-marvels","deadpool-and-wolverine","spider-man-brand-new-day"]},{"id":"watcher","name":"The Watcher","group":"beings","also":"Uatu","what":"A being who observes every universe.","origin":"One of a race of Watchers.","power":"He sees all of the multiverse and has sworn never to interfere.","story":"He narrates What If...?, and breaks his oath when the whole multiverse is in danger.","see":["what-if-s1","what-if-s2","what-if-s3"]},{"id":"the-snap","name":"The Snap and the Blip","group":"events","also":"","what":"The Snap is the moment in 2018 when Thanos, with all six stones, turns half of all living things to dust. The Blip is the common name for that vanishing and for the return five years later.","origin":"Thanos believed the universe did not have enough for everyone.","power":"","story":"In 2023 the Hulk uses the stones to bring everyone back, unchanged, into a world that has moved on five years. Much of what follows deals with the result: lost homes, changed borders, and people who are suddenly five years younger than their friends.","see":["avengers-infinity-war","avengers-endgame","spider-man-far-from-home","wandavision","the-falcon-and-the-winter-soldier"]},{"id":"battle-of-new-york","name":"Battle of New York","group":"events","also":"","what":"Loki's attack on New York in 2012 with the Chitauri army, and the first time the Avengers fight as a team.","origin":"Loki opens a portal above the city with the Tesseract.","power":"","story":"It shows the world that aliens exist. It leaves Tony Stark with lasting anxiety, and leaves alien weapons scattered across the city.","see":["the-avengers","iron-man-3","spider-man-homecoming","avengers-endgame"]},{"id":"sokovia-accords","name":"Sokovia Accords","group":"events","also":"","what":"An agreement signed by 117 countries that puts the Avengers under the control of a United Nations panel.","origin":"Written after the destruction in Sokovia and the deaths in Lagos.","power":"Heroes who sign act only when the panel allows. Those who refuse are treated as criminals.","story":"Tony Stark signs and Steve Rogers refuses, which splits the Avengers in Civil War. She-Hulk: Attorney at Law mentions that the Accords have since been repealed.","see":["captain-america-civil-war","black-widow","she-hulk"]},{"id":"sagas-and-phases","name":"Sagas and Phases","group":"events","also":"","what":"How the studio groups the films and series.","origin":"","power":"","story":"Phases One to Three, from Iron Man (2008) to Spider-Man: Far From Home (2019), make up the Infinity Saga, the story of the stones and Thanos. Phases Four to Six make up the Multiverse Saga.","see":["iron-man","avengers-endgame","spider-man-far-from-home","wandavision","avengers-secret-wars"]}],"titles":{"iron-man":{"t":"Iron Man","y":"2008"},"the-incredible-hulk":{"t":"The Incredible Hulk","y":"2008"},"iron-man-2":{"t":"Iron Man 2","y":"2010"},"thor":{"t":"Thor","y":"2011"},"captain-america-the-first-avenger":{"t":"Captain America: The First Avenger","y":"2011"},"the-avengers":{"t":"The Avengers","y":"2012"},"iron-man-3":{"t":"Iron Man 3","y":"2013"},"thor-the-dark-world":{"t":"Thor: The Dark World","y":"2013"},"captain-america-the-winter-soldier":{"t":"Captain America: The Winter Soldier","y":"2014"},"guardians-of-the-galaxy":{"t":"Guardians of the Galaxy","y":"2014"},"avengers-age-of-ultron":{"t":"Avengers: Age of Ultron","y":"2015"},"ant-man":{"t":"Ant-Man","y":"2015"},"captain-america-civil-war":{"t":"Captain America: Civil War","y":"2016"},"doctor-strange":{"t":"Doctor Strange","y":"2016"},"guardians-of-the-galaxy-vol-2":{"t":"Guardians of the Galaxy Vol. 2","y":"2017"},"spider-man-homecoming":{"t":"Spider-Man: Homecoming","y":"2017"},"thor-ragnarok":{"t":"Thor: Ragnarok","y":"2017"},"black-panther":{"t":"Black Panther","y":"2018"},"avengers-infinity-war":{"t":"Avengers: Infinity War","y":"2018"},"ant-man-and-the-wasp":{"t":"Ant-Man and the Wasp","y":"2018"},"captain-marvel":{"t":"Captain Marvel","y":"2019"},"avengers-endgame":{"t":"Avengers: Endgame","y":"2019"},"spider-man-far-from-home":{"t":"Spider-Man: Far From Home","y":"2019"},"wandavision":{"t":"WandaVision","y":"2021"},"the-falcon-and-the-winter-soldier":{"t":"The Falcon and the Winter Soldier","y":"2021"},"loki-s1":{"t":"Loki (Season 1)","y":"2021"},"black-widow":{"t":"Black Widow","y":"2021"},"what-if-s1":{"t":"What If...? (Season 1)","y":"2021"},"shang-chi":{"t":"Shang-Chi and the Legend of the Ten Rings","y":"2021"},"eternals":{"t":"Eternals","y":"2021"},"hawkeye":{"t":"Hawkeye","y":"2021"},"spider-man-no-way-home":{"t":"Spider-Man: No Way Home","y":"2021"},"doctor-strange-mom":{"t":"Doctor Strange in the Multiverse of Madness","y":"2022"},"ms-marvel":{"t":"Ms. Marvel","y":"2022"},"thor-love-and-thunder":{"t":"Thor: Love and Thunder","y":"2022"},"she-hulk":{"t":"She-Hulk: Attorney at Law","y":"2022"},"black-panther-wakanda-forever":{"t":"Black Panther: Wakanda Forever","y":"2022"},"guardians-holiday-special":{"t":"The Guardians of the Galaxy Holiday Special","y":"2022"},"ant-man-quantumania":{"t":"Ant-Man and the Wasp: Quantumania","y":"2023"},"guardians-of-the-galaxy-vol-3":{"t":"Guardians of the Galaxy Vol. 3","y":"2023"},"secret-invasion":{"t":"Secret Invasion","y":"2023"},"loki-s2":{"t":"Loki (Season 2)","y":"2023"},"the-marvels":{"t":"The Marvels","y":"2023"},"what-if-s2":{"t":"What If...? (Season 2)","y":"2023"},"deadpool-and-wolverine":{"t":"Deadpool & Wolverine","y":"2024"},"agatha-all-along":{"t":"Agatha All Along","y":"2024"},"what-if-s3":{"t":"What If...? (Season 3)","y":"2024"},"captain-america-brave-new-world":{"t":"Captain America: Brave New World","y":"2025"},"thunderbolts":{"t":"Thunderbolts*","y":"2025"},"fantastic-four-first-steps":{"t":"The Fantastic Four: First Steps","y":"2025"},"eyes-of-wakanda":{"t":"Eyes of Wakanda","y":"2025"},"wonder-man":{"t":"Wonder Man","y":"2026"},"spider-man-brand-new-day":{"t":"Spider-Man: Brand New Day","y":"2026"},"visionquest":{"t":"VisionQuest","y":"2026"},"avengers-doomsday":{"t":"Avengers: Doomsday","y":"2026"},"avengers-secret-wars":{"t":"Avengers: Secret Wars","y":"2027"}}};
